// Task 2.2: Buffer temporal y aislamiento semántico de prompt (Guardrail 1)
const inputData = $input.all();
const events = [];

for (const item of inputData) {
  if (item.json.events && Array.isArray(item.json.events)) {
    events.push(...item.json.events);
  } else if (item.json.event_type) {
    events.push(item.json);
  }
}

// Delimitador estricto para evitar Prompt Injection (Anti-LLM01)
const sanitizedBatch = JSON.stringify(events, null, 2);

return [{
  json: {
    raw_logs_prompt: '<raw_logs>\n' + sanitizedBatch + '\n</raw_logs>',
    event_count: events.length,
    sample_src_ip: events[0]?.network?.source_ip || 'UNKNOWN',
    sample_dst_ip: events[0]?.network?.destination_ip || 'UNKNOWN',
    batch_timestamp: new Date().toISOString()
  }
}];

// Guardrails 2 & 3: Validación de Salida Estructurada y Whitelist de Infraestructura
const response = $input.first().json;
const targetIp = response.target_ip;

// Whitelist inmutable de infraestructura crítica
const WHITELIST = ['127.0.0.1', '10.0.0.1', '192.168.1.1', '1.1.1.1'];

if (WHITELIST.includes(targetIp) || targetIp.startsWith('10.0.0.')) {
  return [{
    json: {
      status: 'BLOCKED_BY_GUARDRAIL_3',
      reason: `Intento de auto-DoS detectado sobre IP protegida: ${targetIp}`,
      safe: false
    }
  }];
}

// Guardrail 4: Comando parametrizado estricto (no texto libre)
const safeCommand = `ufw insert 1 deny from ${targetIp} to any`;

return [{
  json: {
    status: 'READY_FOR_HUMAN_APPROVAL',
    incident_id: `INC-2026-${Date.now().toString().slice(-4)}`,
    target_ip: targetIp,
    mitre_id: response.mitre_id || 'T1110.001',
    severity: response.severity || 'ALTA',
    summary: response.summary || 'Ataque coordinado detectado.',
    command: safeCommand,
    confidence: response.confidence || 0.95,
    safe: true
  }
}];
